/**
 * Citations for the Requirements page: cite-requirements writes `<grant>/requirements-citations.json`
 * keyed by requirementKey, and the summary API attaches them to the matching items.
 */

import { createHash } from "node:crypto";

export const REQUIREMENT_CITATIONS_FILE = "requirements-citations.json";
export const REQUIREMENT_CATEGORIES = ["EligibilityCriteria", "RequiredDocuments", "ProjectNarrativeSections", "KeyDeadlines"];

/** Stable per item, so an edited item loses its citations and the others keep theirs. */
export function requirementKey(category, entry) {
  return createHash("sha256")
    .update(JSON.stringify([category, String(entry?.item ?? ""), String(entry?.description ?? "")]))
    .digest("hex")
    .slice(0, 20);
}

/** A copy of `summary` whose requirement items carry `citations` from the saved file, when they match. */
export function withRequirementCitations(summary, file) {
  const byKey = file && typeof file.items === "object" && file.items ? file.items : null;
  if (!byKey || !summary) return summary;
  const out = { ...summary };
  for (const category of REQUIREMENT_CATEGORIES) {
    if (!Array.isArray(summary[category])) continue;
    out[category] = summary[category].map((entry) => {
      const quotes = entry && typeof entry === "object" ? byKey[requirementKey(category, entry)] : null;
      return Array.isArray(quotes) && quotes.length ? { ...entry, citations: quotes } : entry;
    });
  }
  return out;
}
